'use strict';
/* MTG: decision workspace; private OpenAI key stays in Supabase Edge Function. */
const CONFIG=window.MTG_CONFIG||{};
const KEY='mtg-decision-workspace-v1';
const AREAS=[['quartiere','01','Quartiere','Aria, rumore, trasporti e servizi'],['condominio','02','Edificio e condominio','Parti comuni, spese e lavori'],['immobile','03','Immobile','Spazi, impianti, energia e documenti'],['acquisto','04','Prezzo e acquisto','Prezzo, costi e condizioni']];
const PREFS=[['prezzo','Prezzo'],['zona','Zona'],['spazi','Spazi'],['luminosita','Luminosità'],['tranquillita','Tranquillità'],['stato','Condizioni della casa']];
const DOCS=[['annuncio','Annuncio o brochure'],['planimetria','Planimetria catastale'],['ape','APE'],['visura','Visura catastale'],['edilizia','Pratiche edilizie'],['condominio','Verbali / spese condominiali'],['provenienza','Atto di provenienza'],['altro','Altro documento']];
const DEFAULT_GAPS=[
 {id:'quartiere_rumore',area:'quartiere',title:'Rumore e tranquillità',priority:'medium',reason:'Da valutare in relazione alle tue preferenze e alla visita.',action:'Visita l’immobile in momenti diversi e ascolta i rumori nelle camere.',stage:'after_visit',source:'Controllo preliminare'},
 {id:'quartiere_aria',area:'quartiere',title:'Qualità dell’aria nella zona',priority:'low',reason:'Non sono stati collegati dati territoriali ufficiali all’indirizzo.',action:'Consulta dati ARPA o EEA riferiti alla zona, controllando data e copertura.',stage:'any',source:'Dato territoriale non acquisito'},
 {id:'condominio_spese',area:'condominio',title:'Lavori e spese straordinarie',priority:'medium',reason:'Non sono stati ancora caricati verbali o informazioni sulle delibere.',action:'Chiedi spese annuali, verbali recenti e lavori già deliberati.',stage:'any',source:'Documento non disponibile'},
 {id:'immobile_planimetria',area:'immobile',title:'Planimetria e stato di fatto',priority:'medium',reason:'La disponibilità di una planimetria non certifica la regolarità urbanistica.',action:'Richiedi la planimetria e confrontala con la distribuzione osservata; in caso di dubbio coinvolgi un tecnico.',stage:'any',source:'Verifica preliminare'},
 {id:'immobile_ape',area:'immobile',title:'Prestazione energetica dichiarata',priority:'low',reason:'Il dato energetico deve essere ricondotto all’APE della specifica unità.',action:'Richiedi l’APE e verifica classe, data e identificazione dell’immobile.',stage:'any',source:'Documento da acquisire'},
 {id:'acquisto_costi',area:'acquisto',title:'Costo complessivo dell’acquisto',priority:'medium',reason:'Il prezzo dell’annuncio non comprende necessariamente imposte, mediazione e altri oneri.',action:'Stima costi notarili, imposte, agenzia e lavori eventuali.',stage:'any',source:'Prezzo dichiarato'}
];
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const now=()=>new Date().toISOString();
const uid=()=>crypto.randomUUID?crypto.randomUUID():'id_'+Date.now()+'_'+Math.random().toString(16).slice(2);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euros=n=>Number.isFinite(Number(n))&&Number(n)>0?new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number(n)):'Non indicato';
const shortDate=x=>x?new Date(x).toLocaleDateString('it-IT'):'—';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function fresh(){return {version:1,profile:{budget:350000,location:'Milano',purpose:'primary',prefs:Object.fromEntries(PREFS.map(([k])=>[k,3])),custom:[]},homes:[],events:[],intents:[]}}
let state;try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'null')}}catch{state=fresh()}
let current=null,view='research',section='overview',expandedGap='',expertGap='',session=null,supa=null,syncTimer=null,cloudReady=false,cloudError='',busy=false;
function H(){return state.homes.find(h=>h.id===current)}
function log(type,properties={}){state.events.push({id:uid(),at:now(),type,...properties});if(state.events.length>1500)state.events=state.events.slice(-1500)}
function persist(){localStorage.setItem(KEY,JSON.stringify(state));scheduleSync()}
function scheduleSync(){if(!supa||!session||!cloudReady)return;clearTimeout(syncTimer);syncTimer=setTimeout(saveCloud,700)}
async function saveCloud(){if(!supa||!session||!cloudReady)return;const {error}=await supa.from('mtg_workspaces').upsert({user_id:session.user.id,data:state,updated_at:now()},{onConflict:'user_id'});if(error){cloudError=error.message;updateSyncLabel()}else{cloudError='';updateSyncLabel()}}
function updateSyncLabel(){const e=$('#syncLabel');if(e)e.textContent=!session?'Salvataggio locale · Accedi per sincronizzare':!cloudReady?'Salvataggio locale · Cloud da configurare':cloudError?'Errore cloud: '+cloudError:'Sincronizzazione cloud attiva'}
function toast(message){const e=$('#toast');e.textContent=message;e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',4200)}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal();$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}
function render(){ $('#app').innerHTML=({research:researchPage,homes:homesPage,edit:createPage,property:propertyPage,compare:comparePage})[view]();$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===view));$('#accountBtn').textContent=session?'Il mio account':'Accedi';updateSyncLabel();bind() }
function navigate(v,id){view=v;if(id)current=id;if(v==='property'&&!H()){view='homes'};render();scrollTo(0,0)}
function setSection(s){section=s;render();scrollTo(0,0)}
function createHome(){const h={id:uid(),name:'Nuovo immobile · '+shortDate(now()),description:'',link:'',address:'',price:null,sqm:null,floor:'',energy:'',condition:'',condoCosts:'',stage:'online',visited:false,visitedAt:null,visit:{feeling:null,light:null,quiet:null,layout:null,note:''},docs:[],gaps:structuredClone(DEFAULT_GAPS).map(g=>({...g,closed:false,answer:'',evidenceLevel:'missing',history:[]})),analysis:null,aiPros:[],aiCons:[],customTopics:[],decision:{choice:'pending',reason:'',note:'',date:null},expertRequests:[],createdAt:now(),updatedAt:now()};state.homes.push(h);current=h.id;section='details';log('home_created',{homeId:h.id});persist();navigate('property',h.id)}
function homeTitle(h){return h.name||`${h.condition||'Immobile'} · ${shortDate(h.createdAt)}`}
function suggestedHouseName(description,date){const match=String(description||'').match(/\b(monolocale|bilocale|trilocale|quadrilocale|attico|loft|villa|villetta|appartamento)\b/i);return (match?match[1].charAt(0).toUpperCase()+match[1].slice(1).toLowerCase():'Immobile')+' · '+shortDate(date)}
function pageTop(title,description,buttons=''){return `<div class="section-top"><div><div class="eyebrow">mindthegap. / La tua ricerca</div><h1>${title}</h1><p class="muted">${description}</p></div>${buttons}</div>`}
function researchPage(){const p=state.profile;return `${pageTop('Che cosa cerchi nella tua prossima casa?','Definisci una volta le tue priorità. Ogni casa sarà confrontata con gli stessi criteri, anche emotivi.','<div class="btn-row"><button class="btn outline" id="openHomes">Le mie case</button></div>')}<div class="split"><aside class="card sidebar"><div class="eyebrow">COME FUNZIONA</div><h3>Un percorso, più case</h3><p class="smalltext muted">1. Imposta le tue priorità<br>2. Aggiungi annunci e documenti<br>3. Valuta quartiere, condominio, casa e prezzo<br>4. Dopo la visita registra come ti sei sentito<br>5. Approfondisci gap e prendi una decisione</p><div class="rule"></div><span class="tiny" id="syncLabel"></span></aside><div class="main-col"><form class="card stack" id="profileForm"><div class="form-grid"><div class="field"><label>Budget massimo (€)</label><input class="input" id="pBudget" type="number" min="0" value="${esc(p.budget)}"></div><div class="field"><label>Città o zona preferita</label><input class="input" id="pLocation" value="${esc(p.location)}"></div><div class="field"><label>Perché acquisti?</label><select class="input" id="pPurpose"><option value="primary" ${p.purpose==='primary'?'selected':''}>Abitazione principale</option><option value="upgrade" ${p.purpose==='upgrade'?'selected':''}>Cambio casa</option><option value="investment" ${p.purpose==='investment'?'selected':''}>Investimento</option><option value="other" ${p.purpose==='other'?'selected':''}>Altro</option></select></div></div><div class="rule"></div><h3>Quanto contano per te questi aspetti?</h3><p class="hint">1 = poco importante · 5 = decisivo. Il giudizio sulla singola casa sarà registrato separatamente.</p>${PREFS.map(([k,n])=>rangeRow(k,n,p.prefs[k]??3)).join('')}${p.custom.map(c=>rangeRow(c.id,c.name,c.weight)).join('')}<div class="form-grid"><div class="field"><label>Aggiungi un criterio personale</label><input class="input" id="customPref" maxlength="90" placeholder="Es. spazio per lavorare da casa"></div><div class="field"><label>&nbsp;</label><button type="button" class="btn outline" id="addPref">+ Aggiungi criterio</button></div></div><div class="btn-row"><button class="btn" type="submit">Salva le mie preferenze</button><button class="btn outline" type="button" id="startHome">+ Aggiungi un immobile</button></div></form></div></div>`}
function rangeRow(k,label,value){return `<div class="range-row"><label for="pref_${esc(k)}">${esc(label)}</label><input id="pref_${esc(k)}" type="range" min="1" max="5" value="${clamp(value,1,5)}" data-pref="${esc(k)}"><b class="right" data-weight-label="${esc(k)}">${value}/5</b></div>`}
function homesPage(){return `${pageTop('Le mie case','Puoi valutare più immobili in parallelo e tornare a una casa senza perdere informazioni.','<button class="btn" id="newHome">+ Aggiungi una casa</button>')}<div class="stack">${state.homes.length?state.homes.map(h=>`<div class="property-row"><div><div class="eyebrow">${esc(stageLabel(h.stage))} · ${shortDate(h.createdAt)}</div><h3>${esc(homeTitle(h))}</h3><p class="muted">${esc(h.address||'Indirizzo non specificato')} · ${euros(h.price)} · ${h.sqm?esc(h.sqm)+' m²':'Metratura non indicata'}</p><div class="taglist"><span>${h.docs.length} documenti</span><span>${h.gaps.filter(g=>!g.closed).length} questioni aperte</span><span>${h.visited?'Visita effettuata':'Non visitata'}</span></div></div><div class="btn-row"><button class="btn outline small" data-open="${h.id}">Apri</button><button class="btn ghost small" data-remove="${h.id}">Elimina</button></div></div>`).join(''):`<div class="card"><h2>Ancora nessun immobile</h2><p class="muted">Aggiungi il primo annuncio per avviare la valutazione.</p><button class="btn" id="firstHome">Aggiungi la prima casa</button></div>`}</div><p class="tiny mt" id="syncLabel"></p>`}
function createPage(){return '<div class="card">Crea prima un immobile dalla sezione “Le mie case”.</div>'}
function stageLabel(s){return ({online:'Vista online',visited:'Visitata',shortlist:'In shortlist',offer:'Valuto un’offerta',offered:'Offerta presentata',discarded:'Scartata'})[s]||'Vista online'}
function propertyPage(){const h=H();if(!h)return homesPage();const sections=[['details','L’immobile'],['overview','Valutazione'],['visit','Dopo la visita'],['checks','Le verifiche'],['decision','Report e decisione']];return `<div class="section-top"><div><div class="eyebrow">LA MIA RICERCA / ${esc(homeTitle(h))}</div><h1>${esc(homeTitle(h))}</h1><p class="muted">${esc(h.address||'Indirizzo da definire')} · ${euros(h.price)} · ${h.sqm?esc(h.sqm)+' m²':'Superficie da indicare'}</p></div><div class="btn-row"><button class="btn outline small" id="editProfile">Modifica preferenze</button><button class="btn outline small" id="addNext">+ Nuova casa</button></div></div><div class="card mb"><div class="form-grid"><div class="field"><label>A che punto sei con questa casa?</label><select class="input" id="hStage">${['online','visited','shortlist','offer','offered','discarded'].map(s=>`<option value="${s}" ${h.stage===s?'selected':''}>${stageLabel(s)}</option>`).join('')}</select></div><div class="field"><label>Visita effettuata?</label><select class="input" id="hVisited"><option value="no" ${!h.visited?'selected':''}>Non ancora</option><option value="yes" ${h.visited?'selected':''}>Sì, ho visitato l’immobile</option></select></div></div></div><div class="stepper">${sections.map(([id,n],i)=>`<button class="${section===id?'active':''}" data-section="${id}">${i+1}. ${n}</button>`).join('')}</div>${({details:detailsSection,overview:overviewSection,visit:visitSection,checks:checksSection,decision:decisionSection})[section](h)}<p class="tiny mt" id="syncLabel"></p>`}
function detailsSection(h){return `<div class="grid2"><form class="card stack" id="homeForm"><h2>Le informazioni dell’annuncio</h2><div class="field"><label>Nome della casa</label><input class="input" id="hName" value="${esc(h.name)}"></div><div class="field"><label>Descrizione dell’annuncio</label><textarea class="input" id="hDescription" rows="6" placeholder="Incolla qui la descrizione dell’annuncio">${esc(h.description)}</textarea></div><div class="form-grid"><div class="field"><label>Indirizzo o zona</label><input class="input" id="hAddress" value="${esc(h.address)}"></div><div class="field"><label>Link annuncio (Beta)</label><input class="input" id="hLink" type="url" placeholder="https://..." value="${esc(h.link)}"></div><div class="field"><label>Prezzo (€)</label><input class="input" type="number" id="hPrice" min="0" value="${esc(h.price||'')}"></div><div class="field"><label>Superficie (m²)</label><input class="input" type="number" id="hSqm" min="0" value="${esc(h.sqm||'')}"></div><div class="field"><label>Piano</label><input class="input" id="hFloor" value="${esc(h.floor)}"></div><div class="field"><label>Classe energetica dichiarata</label><select class="input" id="hEnergy"><option value="">Non dichiarata</option>${['A4','A3','A2','A1','B','C','D','E','F','G'].map(x=>`<option ${h.energy===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Condizioni</label><select class="input" id="hCondition"><option value="">Non dichiarate</option>${['Nuovo','Ristrutturato','Da ristrutturare','Buono stato'].map(x=>`<option ${h.condition===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Condominio €/mese (se noto)</label><input class="input" type="number" min="0" id="hCondo" value="${esc(h.condoCosts||'')}"></div></div><button class="btn" type="submit">Salva le informazioni</button></form><div class="stack"><div class="card stack"><h2>Hai già dei documenti?</h2><p class="muted smalltext">Carica i PDF testuali o TXT disponibili, anche dopo la visita. MTG registra il file e la data; la presenza del file non equivale a una verifica professionale.</p><div class="field"><label>Tipo di documento</label><select class="input" id="docKind">${DOCS.map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select></div><div class="field"><label>File PDF o TXT (max 8 MB)</label><input class="input" type="file" id="docFile" accept=".pdf,.txt,application/pdf,text/plain"></div><button class="btn outline" id="uploadDoc">+ Aggiungi documento</button><p class="tiny">I testi estratti sono salvati nel workspace; i PDF originali non vengono caricati su Supabase Storage in questa versione. Non usare dati di terzi sensibili senza autorizzazione.</p></div><div class="card stack"><h3>Documenti disponibili (${h.docs.length})</h3>${h.docs.map(d=>`<div class="property-row"><div><b class="smalltext">${esc(d.name)}</b><div class="tiny">${esc(DOCS.find(x=>x[0]===d.kind)?.[1]||'Documento')} · ${shortDate(d.addedAt)} · ${d.text?.length?'Testo leggibile':'Solo presenza dichiarata'}</div></div><button class="btn ghost small" data-del-doc="${d.id}">Rimuovi</button></div>`).join('')||'<p class="muted smalltext">Nessun documento caricato.</p>'}</div><button class="btn" id="runAnalysis">${h.analysis?'Aggiorna analisi con OpenAI':'Analizza la casa con OpenAI'}</button><p class="tiny">Per analisi reale servono accesso Supabase e Edge Function attiva. Nessun risultato fittizio sarà presentato come analisi reale.</p></div></div>`}
function fit(h){const p=state.profile;const values=[];const add=(key,score)=>{const w=Number(p.prefs[key]||0);if(w&&score!=null)values.push([w,score])};if(h.price&&p.budget)add('prezzo',clamp(5-((h.price-p.budget)/Math.max(p.budget,1))*10,1,5));if(h.address&&p.location)add('zona',h.address.toLowerCase().includes(p.location.toLowerCase())?5:null);if(h.visited){add('luminosita',h.visit.light);add('tranquillita',h.visit.quiet);add('spazi',h.visit.layout)};for(const c of p.custom){const value=h.visit.custom?.[c.id];if(value!=null)values.push([Number(c.weight||3),Number(value)])};const sum=values.reduce((a,[w,v])=>a+w*v,0),weights=values.reduce((a,[w])=>a+w,0);const all=Object.values(p.prefs).reduce((a,v)=>a+Number(v),0)+p.custom.reduce((a,c)=>a+c.weight,0);return {score:weights?Math.round(sum/weights/5*100):null,coverage:all?Math.round(weights/all*100):0}}
function areaName(id){return AREAS.find(a=>a[0]===id)?.[2]||'Altro'}
function statusText(h){return h.analysis?.mode==='ai'?'Analisi OpenAI · '+shortDate(h.analysis?.generatedAt):'Verifiche preliminari del catalogo MTG; analisi OpenAI non ancora eseguita'}
function overviewSection(h){const f=fit(h);const total=h.gaps.length,open=h.gaps.filter(g=>!g.closed).length;return `<div class="grid3 mb"><div class="metric"><span>Quanto fa per te</span><b>${f.score==null?'—':f.score+'/100'}</b><span>Basato sul ${f.coverage}% del peso dei criteri; gli altri non sono valutati</span></div><div class="metric"><span>Questioni ancora aperte</span><b>${open}</b><span>${total-open} chiuse da te (non necessariamente verificate)</span></div><div class="metric"><span>Documenti acquisiti</span><b>${h.docs.length}</b><span>Il numero non misura conformità o certezza</span></div></div><div class="info mb"><b>Stato dell'analisi</b> · ${esc(statusText(h))}. Nessun dato territoriale puntuale viene inventato: aria, rumore, OMI e rischi locali richiedono fonti geografiche effettive.</div><div class="grid2">${AREAS.map(([id,n,title,subtitle])=>{const evid=(h.analysis?.areas?.[id]?.evidences||[]);const count=h.gaps.filter(g=>g.area===id&&!g.closed).length;return `<div class="card area-card"><div class="area-head"><div><span class="eyebrow">${n} / ${esc(subtitle)}</span><h2>${esc(title)}</h2></div><span class="badge ${count?'medium':'ok'}">${count} aperte</span></div><div class="rule"></div><b class="smalltext">Evidenze disponibili</b>${evid.length?evid.slice(0,3).map(e=>`<div class="evidence"><div class="smalltext">${esc(e.fact)}</div><div class="tiny">${esc(e.source)} · ${esc(e.quality)}</div></div>`).join(''):'<p class="muted smalltext">Nessuna evidenza verificata. Puoi aggiungere informazioni e documenti.</p>'}<div class="rule"></div><div class="smalltext"><b>${count} verifiche da chiarire</b> · ${h.gaps.filter(g=>g.area===id&&!g.closed).slice(0,2).map(g=>esc(g.title)).join(' · ')||'Nessuna aperta'}</div><button class="btn outline small mt" data-area="${id}">Apri le verifiche →</button></div>`}).join('')}</div><div class="btn-row mt"><button class="btn" id="openChecks">Approfondisci le verifiche</button><button class="btn outline" id="openVisit">${h.visited?'Modifica le sensazioni della visita':'Dopo la visita'}</button><button class="btn outline" id="refreshAnalysis">Aggiorna analisi AI</button></div>`}
function visitSection(h){const v=h.visit;return `<div class="grid2"><form class="card stack" id="visitForm"><div class="eyebrow">LA TUA ESPERIENZA</div><h2>Come ti sei sentito dentro questa casa?</h2><p class="muted smalltext">Queste valutazioni sono personali e specifiche di questo immobile. Non sono prove tecniche né caratteristiche deducibili dall'annuncio.</p><label class="check-row"><input id="visitDone" type="checkbox" ${h.visited?'checked':''}> Ho visitato la casa</label>${h.visited?`<div class="field"><label>Quando? (facoltativo)</label><input id="visitDate" class="input" type="date" value="${esc(h.visitedAt||'')}"></div>${[['feeling','Come ti sei sentito complessivamente?'],['light','Luminosità percepita'],['quiet','Tranquillità percepita'],['layout','Spazi e distribuzione percepiti']].map(([id,label])=>`<div class="range-row"><label>${label}</label><input type="range" min="1" max="5" value="${v[id]??3}" data-emotion="${id}"><b data-emotion-label="${id}">${v[id]??'—'}/5</b></div>`).join('')}${state.profile.custom.map(c=>`<div class="range-row"><label>${esc(c.name)}</label><input type="range" min="1" max="5" data-emotion-custom="${esc(c.id)}" value="${v.custom?.[c.id]??3}"><b>${v.custom?.[c.id]??'—'}/5</b></div>`).join('')}<div class="field"><label>Cosa ti è piaciuto e cosa ti ha lasciato dubbi?</label><textarea class="input" id="visitNote" rows="5" placeholder="Es. Mi piace la zona giorno, ma il rumore dalle finestre mi preoccupa">${esc(v.note)}</textarea></div>`:`<div class="notice">Puoi continuare la valutazione anche senza visita. Quando la farai potrai aggiungere le tue sensazioni.</div>`}<button class="btn" type="submit">Salva la visita e le impressioni</button></form><div class="card stack"><h2>Il tuo punto di vista conta</h2><p class="smalltext">Se la tranquillità per te vale 5/5 e hai percepito rumore, MTG può dare priorità ai controlli sul rumore. Ma una sensazione positiva non rende automaticamente sicura una casa.</p><h3>Indicazioni pratiche</h3><p class="smalltext">Se il rumore è importante: torna in orari diversi, ascolta nelle camere, apri e chiudi le finestre e, se il problema è determinante, valuta una misura acustica professionale.</p><p class="smalltext">Bussare sul muro non è una misura affidabile dell'isolamento acustico.</p><button class="btn outline" id="visitToGaps">Vai alle questioni aperte</button></div></div>`}
function priorityLabel(p){return ({critical:'Critica',high:'Alta',medium:'Media',low:'Da approfondire'})[p]||'Da valutare'}
function listGap(h,g){return `<div class="gap" id="gap_${esc(g.id)}"><div class="gap-header"><div><div class="gap-label">${esc(areaName(g.area))} · ${esc(g.source||'')}${g.stage==='after_visit'?' · Dopo la visita':''}</div><div class="gap-title">${esc(g.title)}</div><div class="taglist mt"><span class="badge ${g.closed?'ok':g.priority==='critical'||g.priority==='high'?'high':g.priority==='medium'?'medium':'low'}">${g.closed?'Chiusa da te':priorityLabel(g.priority)}</span><span class="badge">${esc(g.evidenceLevel==='documented'?'Documento presente':g.evidenceLevel==='declared'?'Dichiarazione buyer':'Informazione da chiarire')}</span></div></div><button class="btn outline small" data-expand="${esc(g.id)}">${expandedGap===g.id?'Chiudi dettagli':'Approfondisci'}</button></div>${expandedGap===g.id?`<div class="gap-details stack"><div><b class="smalltext">Perché è rilevante</b><p class="smalltext">${esc(g.reason||'Non ancora analizzata')}</p></div><div class="info"><b>Cosa fare adesso</b><p>${esc(g.action||'Richiedi ulteriori informazioni.')}</p></div><div class="field"><label>La tua risposta o un riscontro ricevuto</label><textarea class="input" rows="3" data-gap-answer="${esc(g.id)}" placeholder="Es. L'agente mi ha comunicato che...">${esc(g.answer||'')}</textarea></div><div class="btn-row"><button class="btn outline small" data-save-answer="${esc(g.id)}">Salva risposta</button><button class="btn outline small" data-close-gap="${esc(g.id)}">${g.closed?'Riapri la questione':'Per me è chiusa'}</button><button class="btn outline small" data-expert="${esc(g.id)}">Attiva specialista</button><button class="btn ghost small" data-copy-question="${esc(g.id)}">Copia domanda</button></div><p class="tiny">Chiusa da te = tua scelta, non verifica professionale. Puoi aggiungere un documento dalla scheda dell'immobile.</p>${g.history?.length?`<details><summary class="smalltext">Storico (${g.history.length})</summary>${g.history.map(t=>`<div class="tiny">${shortDate(t.at)} · ${esc(t.event)} ${esc(t.detail||'')}</div>`).join('')}</details>`:''}</div>`:''}</div>`}
function checksSection(h){const open=h.gaps.filter(g=>!g.closed).length;return `<div class="section-top"><div><h2>Evidenze, gap e prossime azioni</h2><p class="muted smalltext">${open} aperte · ${h.gaps.length-open} chiuse da te. Le priorità dipendono dalle informazioni della casa, dalla fase e dalle tue preferenze.</p></div><div class="btn-row"><button class="btn outline small" id="exportQuestions">Esporta domande per Excel</button><button class="btn outline small" id="goDocs">+ Documento</button></div></div><div class="info mb">Ogni gap resta aperto finché non lo chiudi tu. Un file caricato o una risposta non costituiscono automaticamente una conformità verificata.</div>${AREAS.map(([id,n,title])=>`<div class="card mb"><div class="area-head"><h2>${n} · ${esc(title)}</h2><span class="badge">${h.gaps.filter(g=>g.area===id&&!g.closed).length} aperte</span></div>${h.gaps.filter(g=>g.area===id).sort((a,b)=>priorityWeight(b.priority)-priorityWeight(a.priority)).map(g=>listGap(h,g)).join('')||'<p class="muted smalltext">Nessuna questione in questa area. Non significa che tutte le verifiche siano concluse.</p>'}</div>`).join('')}<div class="card stack"><h3>Aggiungi un tema da approfondire</h3><p class="smalltext muted">Puoi proporre qualsiasi dubbio. MTG lo collega alla categoria pertinente e, se sei autenticato, può analizzarlo con OpenAI.</p><div class="field"><label>Il tuo tema</label><textarea class="input" id="newTopic" placeholder="Es. Vorrei capire se posso abbattere la parete tra cucina e soggiorno"></textarea></div><button class="btn outline" id="addTopic">+ Aggiungi alla valutazione</button></div>`}
function priorityWeight(p){return ({critical:4,high:3,medium:2,low:1})[p]||0}
function decisionSection(h){const f=fit(h);const open=h.gaps.filter(g=>!g.closed);const ai=h.analysis;const pros=ai?.pros||[],cons=ai?.cons||[];return `<div class="grid2 mb"><div class="card"><div class="eyebrow">PREFERENZE</div><h2>Quanto fa per te</h2><div class="metric"><b>${f.score==null?'Non valutabile':f.score+'/100'}</b><span>Solo ${f.coverage}% del peso dei criteri risulta valutato. Le sensazioni vengono considerate solo dopo la visita.</span></div></div><div class="card"><div class="eyebrow">VERIFICHE</div><h2>Cosa resta aperto</h2><div class="metric"><b>${open.length}</b><span>Questioni da chiarire; la chiusura manuale non costituisce certificazione.</span></div></div></div><div class="proscons mb"><div class="card"><h3>Perché potrebbe fare per te</h3><ul>${pros.length?pros.map(x=>`<li>${esc(x)}</li>`).join(''):'<li>Salva le tue preferenze ed esegui l’analisi AI per ottenere motivazioni personalizzate.</li>'}</ul></div><div class="card"><h3>Perché potresti non sceglierla</h3><ul>${cons.length?cons.map(x=>`<li>${esc(x)}</li>`).join(''):`<li>Ci sono ${open.length} verifiche aperte. Non sono necessariamente problemi accertati.</li>`}</ul></div></div><div class="card mb"><div class="area-head"><div><h2>Report approfondito della casa</h2><p class="smalltext muted">Annuncio, storico datato, preferenze, giudizi dopo la visita, documenti, evidenze, gap, pro e contro, limiti dell'analisi e decisione.</p></div><b style="font-size:28px">15 €</b></div><div class="btn-row"><button class="btn" id="reportIntent">${h.reportUnlocked?'Apri report ed esporta PDF':'Simula acquisto report · 15 €'}</button><span class="tiny">Nessun pagamento reale nell'MVP.</span></div></div><form class="card stack" id="decisionForm"><h2>Qual è la tua decisione oggi?</h2><div class="field"><label>Stato</label><select class="input" id="decisionChoice"><option value="pending" ${h.decision.choice==='pending'?'selected':''}>Voglio ancora approfondire</option><option value="offer" ${h.decision.choice==='offer'?'selected':''}>Sto valutando un'offerta</option><option value="offered" ${h.decision.choice==='offered'?'selected':''}>Ho presentato un'offerta</option><option value="no" ${h.decision.choice==='no'?'selected':''}>Ho deciso di non procedere</option></select></div><div class="field"><label>Motivo della rinuncia, se non procedi</label><select class="input" id="decisionReason"><option value="">Seleziona il motivo</option>${[['prezzo','Prezzo e costi'],['tecnico','Questioni tecniche o documentali'],['emotivo','Sensazioni durante la visita'],['preferenze','Non risponde alle mie esigenze'],['altra','Ho trovato un’alternativa'],['altro','Altro']].map(([v,n])=>`<option value="${v}" ${h.decision.reason===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Note (facoltative)</label><textarea class="input" id="decisionNote" rows="3">${esc(h.decision.note)}</textarea></div><button class="btn" type="submit">Registra la mia decisione</button></form>`}
function comparePage(){if(state.homes.length<2)return `${pageTop('Confronta le case','Aggiungi almeno due immobili per costruire il confronto.')}<div class="card"><button class="btn" id="compareAdd">+ Aggiungi un altro immobile</button></div>`;return `${pageTop('Confronta le tue case','Preferenze condivise, impressioni specifiche per immobile e verifiche tenute separate.')}<div class="card mb"><div class="info">Il confronto di base è consultabile; il report comparativo approfondito è disponibile tramite intenzione d'acquisto simulata. Nessun pagamento reale.</div><div style="overflow:auto;margin-top:14px"><table class="comparison"><thead><tr><th>Criterio</th>${state.homes.map(h=>`<th>${esc(homeTitle(h))}</th>`).join('')}</tr></thead><tbody>${[['Prezzo',h=>euros(h.price)],['Superficie',h=>h.sqm?`${esc(h.sqm)} m²`:'—'],['Compatibilità',h=>fit(h).score==null?'Non valutabile':`${fit(h).score}/100 (${fit(h).coverage}% criteri)`],['Visita',h=>h.visited?'Effettuata':'Da fare'],['Sensazione complessiva',h=>h.visited&&h.visit.feeling?`${h.visit.feeling}/5`:'Non valutata'],['Questioni aperte',h=>String(h.gaps.filter(g=>!g.closed).length)],['Documenti',h=>String(h.docs.length)],['Decisione',h=>({pending:'Da valutare',offer:'Valuto offerta',offered:'Offerta presentata',no:'Scartata'})[h.decision.choice]||'—']].map(([name,fn])=>`<tr><td>${name}</td>${state.homes.map(h=>`<td>${fn(h)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="card"><div class="area-head"><div><h2>Report comparativo</h2><p class="muted smalltext">Pro e contro per ciascuna casa, criteri condivisi, gap e differenze nelle evidenze.</p></div><b style="font-size:25px">29 €</b></div><button class="btn mt" id="compareIntent">${state.compareUnlocked?'Esporta confronto':'Simula acquisto confronto · 29 €'}</button><p class="tiny">Pacchetto e prezzo da validare. Nessun addebito reale.</p></div>`}
