function aiProfile(){const p=state.profile;return {budget:p.budget,location:p.location,purpose:p.purpose,weights:p.prefs,custom:p.custom}}
function aiProperty(h){return {description:h.description,link:h.link,area:h.address,price:h.price,sqm:h.sqm,floor:h.floor,energy:h.energy,condition:h.condition,condoCosts:h.condoCosts}}
async function ai(operation,params){if(!supa||!session){accountDialog();throw Error('Accedi per utilizzare l’analisi OpenAI')}const {data,error}=await supa.functions.invoke('mtg-ai',{body:{operation,...params}});if(error){let msg=error.message;try{const e=await error.context.json();msg=e.error||msg}catch{}throw Error(msg)}if(data?.error)throw Error(data.error);return data}
async function runAnalysis(h){if(busy)return;if(!h.description.trim()&&!h.docs.length)return toast('Aggiungi prima una descrizione o un documento');busy=true;toast('Analisi in corso, sui dati effettivamente disponibili…');try{const data=await ai('workspace_analysis',{property:aiProperty(h),buyerProfile:aiProfile(),visitStatus:h.visited?'visited':'not_visited',visitNotes:h.visit,documents:h.docs.map(d=>({name:d.name,kind:d.kind,text:d.text})),existingGaps:h.gaps.map(g=>({id:g.id,title:g.title,area:g.area,closed:g.closed,answer:g.answer,source:g.source}))});if(!data?.analysis?.areas)throw Error('Risposta incompleta dal backend');h.analysis={...data.analysis,mode:'ai',generatedAt:now()};const generated=(data.analysis.gaps||[]).slice(0,22);for(const g of generated){let id=String(g.id||'').replace(/[^a-z0-9_]/g,'').slice(0,70);if(!id)continue;const found=h.gaps.find(x=>x.id===id);if(found){const buyerFields={closed:found.closed,answer:found.answer,evidenceLevel:found.evidenceLevel,history:found.history};Object.assign(found,{area:g.area,title:g.title,priority:g.priority,reason:g.reason,action:g.action,source:g.source,stage:g.stage},buyerFields)}else{if(h.gaps.some(x=>x.title.toLowerCase()===String(g.title).toLowerCase()))continue;h.gaps.push({...g,id,closed:false,answer:'',evidenceLevel:'missing',history:[{at:now(),event:'Generata dall’analisi AI'}]})}}h.updatedAt=now();log('analysis_completed',{homeId:h.id,gapCount:generated.length});persist();render();toast('Analisi aggiornata. Le risposte e le chiusure precedenti sono state conservate.')}catch(e){toast('Analisi non riuscita: '+e.message)}finally{busy=false}}
async function readFile(file){if(file.size>8*1024*1024)throw Error('File troppo grande: limite 8 MB');if(/\.txt$/i.test(file.name))return (await file.text()).slice(0,35000);if(!/\.pdf$/i.test(file.name))throw Error('Carica PDF testuale o TXT');const pdfjs=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;let t='';for(let i=1;i<=Math.min(20,pdf.numPages);i++){const page=await pdf.getPage(i);const content=await page.getTextContent();t+=`\n[pagina ${i}] `+content.items.map(x=>x.str||'').join(' ');if(t.length>35000)break}if(t.trim().length<50)throw Error('PDF scansito o senza testo leggibile. Per ora non è disponibile OCR.');return t.slice(0,35000)}
function showExpert(h){const g=h.gaps.find(g=>g.id===expertGap);if(!g)return;modal(`<div class="stack"><div class="eyebrow">SERVIZIO PROFESSIONALE · MVP SIMULATO</div><h2>Approfondisci: ${esc(g.title)}</h2><p class="smalltext">Il servizio comprende soltanto gli aspetti indicati nell'incarico e il relativo report. Verifiche aggiuntive richiedono un prezzo separato.</p><div class="info"><b>Perimetro proposto</b><p>${esc(g.action)}</p></div><div class="field"><label>Tipo di intervento</label><select class="input" id="expertService"><option value="video">Videoconsulenza (prezzo illustrativo €200)</option><option value="inspection">Ispezione (prezzo illustrativo €500)</option></select></div><div class="field"><label>Altri aspetti da includere (richiedono preventivo)</label><textarea class="input" id="expertExtra" placeholder="Indica eventuali verifiche extra"></textarea></div><div class="notice">Non sono prenotazioni reali. Non è assegnato alcun professionista e nessun pagamento sarà addebitato.</div><div class="btn-row"><button class="btn" id="expertSubmit">Registra interesse</button><button class="btn outline" data-close>Chiudi</button></div></div>`);$('#expertSubmit').onclick=()=>{const service=$('#expertService').value,extra=$('#expertExtra').value.trim();h.expertRequests.push({at:now(),gapId:g.id,scope:g.title,service,extra,simulation:true});log('expert_interest',{homeId:h.id,gapId:g.id,service,realPayment:false});persist();$('#modal').close();toast('Interesse registrato. Il report professionale non è stato simulato come verifica reale.')};$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}
function csvCell(v){return '"'+String(v??'').replaceAll('"','""')+'"'}
function download(name,type,content){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function exportExcelCSV(h){const rows=[['Area','Priorità','Questione','Prossimo passo','Stato','Risposta buyer','Fonte'],...h.gaps.map(g=>[areaName(g.area),priorityLabel(g.priority),g.title,g.action,g.closed?'Chiusa da te':'Aperta',g.answer,g.source])];download('MTG_Domande_'+slug(h.name)+'.csv','text/csv;charset=utf-8','\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'));log('questions_exported',{homeId:h.id});persist()}
function slug(t){return String(t||'casa').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'_').slice(0,48)}
function printWindow(html){const w=window.open('','_blank');if(!w){toast('Consenti i popup per esportare in PDF');return}w.document.write(`<!doctype html><html lang="it"><head><meta charset="utf-8"><title>MTG Report</title><style>body{font:12px/1.5 Arial,sans-serif;color:#172b40;max-width:840px;margin:32px auto}h1{color:#0f3460;font-size:26px}h2{border-bottom:1px solid #ddd;margin-top:26px;padding-bottom:5px}h3{font-size:14px;margin-bottom:3px}section{page-break-inside:avoid;margin-bottom:14px}.label{font-size:11px;color:#66778b}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ddd;text-align:left;padding:7px}p{margin:5px 0}small{color:#607588}</style></head><body>${html}<script>window.onload=()=>{setTimeout(()=>window.print(),400)}<\/script></body></html>`);w.document.close()}
function exportPrintReport(h){const f=fit(h);const page=`<h1>mindthegap. · Dossier immobile</h1><small>Emesso il ${new Date().toLocaleString('it-IT')} · Snapshot, non certificazione</small><h2>${esc(homeTitle(h))}</h2><p>${esc(h.address)} · ${euros(h.price)} · ${h.sqm||'—'} m²</p><h2>Annuncio originale inserito</h2><p>${esc(h.description)}</p><h2>Preferenze della ricerca</h2><p>Budget ${euros(state.profile.budget)} · Zona ${esc(state.profile.location)} · ${PREFS.map(([k,n])=>`${n}: ${state.profile.prefs[k]}/5`).join(' · ')}${state.profile.custom.map(x=>` · ${esc(x.name)}: ${x.weight}/5`).join('')}</p><h2>Compatibilità e limiti</h2><p>Compatibilità ${f.score==null?'non valutabile':f.score+'/100'} · Criteri valutati ${f.coverage}% del peso complessivo. Il punteggio non misura sicurezza o conformità.</p><h2>Visita e sensazioni</h2><p>${h.visited?`Visita effettuata il ${esc(h.visitedAt||'giorno non indicato')}. Sensazione ${h.visit.feeling??'—'}/5; luce ${h.visit.light??'—'}/5; tranquillità ${h.visit.quiet??'—'}/5; spazi ${h.visit.layout??'—'}/5. ${esc(h.visit.note)}`:'Non ancora visitata'}</p><h2>Evidenze e documenti inseriti</h2>${h.docs.map(d=>`<p>• ${esc(d.name)} (${esc(d.kind)}), aggiunto il ${shortDate(d.addedAt)} — testo ${d.text?.length?'estratto':'non disponibile'}</p>`).join('')||'<p>Nessun documento caricato</p>'}${AREAS.map(([a,,n])=>`<h2>${esc(n)}</h2>${(h.analysis?.areas?.[a]?.evidences||[]).map(x=>`<section><b>${esc(x.fact)}</b><p class="label">${esc(x.source)} · ${esc(x.quality)}</p></section>`).join('')||'<p>Nessuna evidenza da analisi AI disponibile.</p>'}${h.gaps.filter(g=>g.area===a).map(g=>`<section><h3>${esc(g.title)} · ${g.closed?'Chiusa dal buyer':'Aperta'}</h3><p>${esc(g.reason)}</p><p><b>Cosa fare:</b> ${esc(g.action)}</p><p><b>Risposta buyer:</b> ${esc(g.answer||'Non disponibile')}</p><p class="label">${esc(g.source)} · ${esc(g.history?.map(x=>shortDate(x.at)+' '+x.event).join('; ')||'')}</p></section>`).join('')}`).join('')}<h2>Perché comprarla / perché non comprarla</h2><b>Pro</b><ul>${(h.analysis?.pros||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Analisi non effettuata</li>'}</ul><b>Contro</b><ul>${(h.analysis?.cons||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Analisi non effettuata</li>'}</ul><h2>Decisione</h2><p>${esc(h.decision.choice)} · ${esc(h.decision.reason||'')} · ${esc(h.decision.note||'')} · ${shortDate(h.decision.date)}</p><p><small>Informazioni riportate a scopo decisionale preliminare. Un documento caricato non dimostra conformità. Le informazioni territoriali non verificate e le prestazioni professionali simulate non hanno valore di accertamento.</small></p>`;printWindow(page);log('report_print',{homeId:h.id});persist()}
function exportPrintCompare(){const cells=state.homes.map(h=>({h,f:fit(h)}));printWindow(`<h1>mindthegap. · Confronto immobili</h1><small>Generato il ${new Date().toLocaleString('it-IT')}; valutazioni indicative, informazioni non certificate</small><table><tr><th>Immobile</th><th>Prezzo</th><th>Compatibilità</th><th>Copertura criteri</th><th>Gap aperti</th></tr>${cells.map(({h,f})=>`<tr><td>${esc(homeTitle(h))}</td><td>${euros(h.price)}</td><td>${f.score??'—'}/100</td><td>${f.coverage}%</td><td>${h.gaps.filter(g=>!g.closed).length}</td></tr>`).join('')}</table>${cells.map(({h})=>`<h2>${esc(homeTitle(h))}</h2><b>Perché potrebbe fare per te</b><ul>${(h.analysis?.pros||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Analisi non disponibile</li>'}</ul><b>Perché potrebbe non fare per te</b><ul>${(h.analysis?.cons||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Analisi non disponibile</li>'}</ul>`).join('')}`);log('comparison_print');persist()}
function accountDialog(){if(session){modal(`<h2>Il mio account</h2><p>${esc(session.user.email||'Accesso Supabase')}</p><p class="muted smalltext">${cloudReady?'Sincronizzazione workspace attiva':'Salvataggio locale attivo. Applica la migrazione SQL per abilitare il cloud.'}</p><div class="btn-row"><button class="btn outline" id="logout">Esci</button><button class="btn ghost" data-close>Chiudi</button></div>`);$('#logout').onclick=async()=>{await supa.auth.signOut();session=null;cloudReady=false;$('#modal').close();render()};$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close());return}modal(`<h2>Accedi a MTG</h2><p class="smalltext muted">Per usare OpenAI e sincronizzare le valutazioni, accedi tramite email. Il collegamento Supabase resta quello del progetto esistente.</p><form id="loginForm" class="stack"><div class="field"><label>Email</label><input class="input" id="loginEmail" type="email" required placeholder="nome@email.it"></div><button class="btn" type="submit">Invia link di accesso</button></form><p class="tiny">Il login richiede configurazione Supabase Auth e Redirect URLs per il sito GitHub Pages.</p><button class="btn ghost mt" data-close>Chiudi</button>`);$('#loginForm').onsubmit=async e=>{e.preventDefault();if(!supa)return toast('Configura web/config.js con Supabase URL e publishable key');const email=$('#loginEmail').value.trim();const {error}=await supa.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+location.pathname}});toast(error?'Login non riuscito: '+error.message:'Controlla la tua email per il link di accesso');if(!error)$('#modal').close()};$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}
async function loadCloud(){if(!supa||!session)return;const {data,error}=await supa.from('mtg_workspaces').select('data').eq('user_id',session.user.id).maybeSingle();if(error){cloudReady=false;cloudError=error.message;updateSyncLabel();return}cloudReady=true;cloudError='';if(data?.data?.version){if(!state.homes.length || confirm('Esiste un workspace salvato su Supabase. Vuoi caricarlo? (La versione locale corrente sarà sostituita.)')){state={...fresh(),...data.data};localStorage.setItem(KEY,JSON.stringify(state))}}else{await saveCloud()}render()}
async function init(){render();if(!CONFIG.supabaseUrl||!CONFIG.supabasePublishableKey)return;try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');supa=createClient(CONFIG.supabaseUrl,CONFIG.supabasePublishableKey);const {data}=await supa.auth.getSession();session=data.session;supa.auth.onAuthStateChange((_event,s)=>{const was=session?.user?.id;session=s;if(s&&s.user.id!==was)loadCloud();else if(!s){cloudReady=false;render()}else updateSyncLabel()});if(session)await loadCloud();else render()}catch(e){cloudError=e.message;render()}}
init();
